-- Migration 0002: chat history (AI <-> user) + API clients.
-- Conventions:
--   * ids are TEXT (UUIDv7 / ULID generated by the app, so they sort by time).
--   * timestamps are INTEGER Unix epoch milliseconds (UTC).
--   * booleans are INTEGER 0/1 with CHECK.
--   * D1 enforces foreign keys by default; deletes cascade from users downwards.
--   * Attachment bytes live in R2 (bucket nvx-assets, binding ASSETS_BUCKET, once enabled);
--     D1 stores only the object key and metadata.
-- No UI or endpoints use these tables yet.

CREATE TABLE users (
  id            TEXT PRIMARY KEY NOT NULL,
  created_at    INTEGER NOT NULL DEFAULT (unixepoch('subsec') * 1000),
  display_name  TEXT,
  -- Auth provider fields (nullable until an auth method is chosen).
  auth_provider TEXT,            -- e.g. 'github', 'google', 'passkey', 'cf-access'
  auth_subject  TEXT,            -- provider's stable user id ("sub")
  email         TEXT,
  CHECK ((auth_provider IS NULL) = (auth_subject IS NULL))
) STRICT;

-- One account per provider identity (NULLs are distinct, so anonymous users are allowed).
CREATE UNIQUE INDEX users_auth_identity_uq ON users (auth_provider, auth_subject);
CREATE INDEX users_email_idx ON users (email) WHERE email IS NOT NULL;

CREATE TABLE conversations (
  id         TEXT PRIMARY KEY NOT NULL,
  user_id    TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  title      TEXT,
  model      TEXT,               -- default model for new messages in this conversation
  created_at INTEGER NOT NULL DEFAULT (unixepoch('subsec') * 1000),
  updated_at INTEGER NOT NULL DEFAULT (unixepoch('subsec') * 1000),
  archived   INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))
) STRICT;

-- Sidebar listing: a user's conversations, newest activity first, optionally hiding archived.
CREATE INDEX conversations_user_updated_idx ON conversations (user_id, archived, updated_at DESC);

CREATE TABLE messages (
  id              TEXT PRIMARY KEY NOT NULL,
  conversation_id TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  role            TEXT NOT NULL CHECK (role IN ('user', 'assistant', 'system', 'tool')),
  content         TEXT NOT NULL,
  tokens_in       INTEGER CHECK (tokens_in IS NULL OR tokens_in >= 0),
  tokens_out      INTEGER CHECK (tokens_out IS NULL OR tokens_out >= 0),
  model           TEXT,          -- model that produced (assistant) or received (user) this turn
  created_at      INTEGER NOT NULL DEFAULT (unixepoch('subsec') * 1000)
) STRICT;

-- Loading a conversation in order (and paging by created_at).
CREATE INDEX messages_conversation_created_idx ON messages (conversation_id, created_at, id);

CREATE TABLE attachments (
  id         TEXT PRIMARY KEY NOT NULL,
  message_id TEXT NOT NULL REFERENCES messages (id) ON DELETE CASCADE,
  r2_key     TEXT NOT NULL UNIQUE,  -- e.g. 'u/<user_id>/c/<conversation_id>/<attachment_id>'
  mime       TEXT NOT NULL,
  size       INTEGER NOT NULL CHECK (size >= 0),  -- bytes
  created_at INTEGER NOT NULL DEFAULT (unixepoch('subsec') * 1000)
) STRICT;

CREATE INDEX attachments_message_idx ON attachments (message_id);

-- Other AIs / services connecting with an API key we issue and can revoke.
-- Only a hash of the key is stored (SHA-256 hex of the full key); the key is shown once at creation.
CREATE TABLE api_clients (
  id         TEXT PRIMARY KEY NOT NULL,
  name       TEXT NOT NULL,
  key_hash   TEXT NOT NULL UNIQUE,
  scopes     TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(scopes) AND json_type(scopes) = 'array'),
  rate_limit INTEGER NOT NULL DEFAULT 60 CHECK (rate_limit > 0),  -- requests per minute
  created_at INTEGER NOT NULL DEFAULT (unixepoch('subsec') * 1000),
  revoked_at INTEGER                                              -- NULL = active
) STRICT;

-- key_hash lookups use the UNIQUE index; this one lists active clients for admin views.
CREATE INDEX api_clients_active_created_idx ON api_clients (created_at DESC) WHERE revoked_at IS NULL;

UPDATE schema_meta SET value = '2', updated_at = unixepoch('subsec') * 1000 WHERE key = 'schema_version';
